/// Sanctum of Ugin is `Coverage::Implemented`.  It prints `{T}: Add {C}` as a
/// non-intrinsic mana ability (the land has no basic subtype), so the activation
/// sits in `legal.abilities` and not `legal.mana_abilities`.  Activating it puts
/// one colourless mana in the pool without using the stack.
///
/// This test strikes that single sentence: the offer lands in the right list,
/// pressing it taps the land and fills the pool with `{C}`, and the stack stays
/// empty.  The cast trigger is not exercised here because every colorless spell
/// with mana value 7 or greater available in the pool requires an X choice the
/// harness cannot answer through `pass_until`.
#[test]
fn sanctum_of_ugin_taps_for_one_colorless_via_printed_ability() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(41, forest())
        .battlefield(0, &[sanctum_of_ugin()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let sanctum = on_battlefield(&engine, p0, sanctum_of_ugin()).expect("the Sanctum is out");

    // The Sanctum prints no basic land type, so the CR 305.6 shortcut does not
    // apply: its mana ability is in `legal.abilities`, not `legal.mana_abilities`.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.mana_abilities.contains(&sanctum),
        "no basic land type means no CR 305.6 shortcut: {:?}",
        legal.mana_abilities
    );
    assert!(
        legal.abilities.contains(&(sanctum, 0)),
        "the printed {{T}}: Add {{C}} is an ordinary activation in legal.abilities: {:?}",
        legal.abilities
    );

    let before = engine.state().players[0]
        .mana_pool
        .available(ManaColor::Colorless);
    let before_total = engine.state().players[0].mana_pool.total();
    activate(&mut engine, p0, sanctum_of_ugin(), 0);

    assert!(
        stack_is_empty(&engine),
        "a mana ability never uses the stack (CR 605.3b)"
    );
    assert!(
        is_tapped(&engine, sanctum),
        "the {{T}} in the cost tapped the land"
    );
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Colorless),
        before + 1,
        "{{T}}: Add {{C}} added exactly one colourless"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        before_total + 1,
        "and nothing else came with it"
    );
}

/// The Black Gate is `Coverage::Partial`: the third ability is not
/// implemented.  The two implemented halves are the shockland-style entry —
/// pay 3 life or enter tapped — and `{T}: Add {B}`.
///
/// Two games prove the two arms of the entry question.  In the first, the
/// controller declines the payment: the Gate enters tapped and no life is
/// lost.  In the second, the controller accepts: the Gate enters untapped and
/// life falls by exactly 3.  Two games because one land drop per turn is one
/// arm per game.
#[test]
fn the_black_gate_enters_untapped_for_three_life_or_tapped_for_free() {
    let p0 = PlayerId::new(0);

    // ── Arm 1: decline → enters tapped, no life lost.
    {
        let mut engine = Duel::new(43, forest()).hand(0, &[the_black_gate()]).start();
        keep_mulligans(&mut engine);
        reach_main_phase(&mut engine, p0);

        let life_before = engine.state().players[0].life;
        let land = in_hand(&engine, p0, the_black_gate()).expect("the Gate is in hand");
        engine
            .apply(p0, PlayerAction::PlayLand { card: land })
            .unwrap();

        let Pending::YesNo {
            player,
            prompt: crate::choice::YesNoPrompt::PayLifeOrEnterTapped { amount },
            ..
        } = engine.pending().clone()
        else {
            panic!("expected PayLifeOrEnterTapped, got {:?}", engine.pending())
        };
        assert_eq!(player, p0, "the controller decides");
        assert_eq!(amount, 3, "the Gate asks for 3 life");

        engine.apply(p0, PlayerAction::YesNo(false)).unwrap();
        pass_until(&mut engine, stack_is_empty);

        let gate =
            on_battlefield(&engine, p0, the_black_gate()).expect("the Gate is on the battlefield");
        assert!(
            is_tapped(&engine, gate),
            "declining the payment leaves the Gate tapped"
        );
        assert_eq!(
            engine.state().players[0].life,
            life_before,
            "declining costs no life"
        );
    }

    // ── Arm 2: accept → enters untapped, costs 3 life.
    {
        let mut engine = Duel::new(44, forest()).hand(0, &[the_black_gate()]).start();
        keep_mulligans(&mut engine);
        reach_main_phase(&mut engine, p0);

        let life_before = engine.state().players[0].life;
        let land = in_hand(&engine, p0, the_black_gate()).expect("the Gate is in hand");
        engine
            .apply(p0, PlayerAction::PlayLand { card: land })
            .unwrap();

        let Pending::YesNo {
            player,
            prompt: crate::choice::YesNoPrompt::PayLifeOrEnterTapped { amount },
            ..
        } = engine.pending().clone()
        else {
            panic!("expected PayLifeOrEnterTapped, got {:?}", engine.pending())
        };
        assert_eq!(player, p0);
        assert_eq!(amount, 3);

        engine.apply(p0, PlayerAction::YesNo(true)).unwrap();
        pass_until(&mut engine, stack_is_empty);

        let gate =
            on_battlefield(&engine, p0, the_black_gate()).expect("the Gate is on the battlefield");
        assert!(
            !is_tapped(&engine, gate),
            "paying 3 life leaves the Gate untapped"
        );
        assert_eq!(
            engine.state().players[0].life,
            life_before - 3,
            "the payment costs exactly 3 life"
        );
    }
}

/// The thirteen modal double-faced cards round J added, named rather than
/// counted.
///
/// The sweep below is the test; this list is what keeps it from going
/// quiet. A walk that stopped finding cards would pass every assertion it
/// makes, and a floor sitting between two growing numbers is the fault the
/// land-arrival sweep was repaired for. These are the thirteen a person
/// read against their printing, so the sweep is asked to have reached each
/// of them by name -- which also makes a re-filed or renamed face a
/// failure here rather than a silent shrinking of the population.
/// The spell-fronted land backs whose arrival asks a question, and so the
/// exact set this sweep does not play. Filled from the sweep's own first
/// run rather than from a grep, for the reason the enters-tapped floor is:
/// a list bounded by one instrument and read by another bounds nothing.
const ARRIVALS_THAT_ASK: &[&str] = &[
    "Agadeem, the Undercrypt",
    "Boggart Bog",
    "Emeria, Shattered Skyclave",
    "Fell Mire",
    "Garden of Freyalise",
    "Hydroelectric Laboratory",
    "Mystic Peak",
    "Razorgrass Field",
    "Sea Gate, Reborn",
    "Shatterskull, the Hammer Pass",
    "Soporific Springs",
    "Tanglespan Bridgeworks",
    "Turntimber, Serpentine Wood",
    "Volcanic Fissure",
    "Witch-Blessed Meadow",
];

/// What the sweep reached, less a margin for a card leaving the pool: **35**
/// played on 22.09.2026 over a pool of 2716, beside the fifteen in
/// [`ARRIVALS_THAT_ASK`] that it does not play. Read off the sweep's own run
/// rather than off a grep of the card files, for the reason `validate`'s
/// enters-tapped floor is: a count taken by one instrument bounds nothing
/// about another.
///
/// It reached 55 this morning, and the twenty that left are why this sweep
/// needed a neighbour rather than a tighter assertion. A **transforming**
/// double-faced card is cast as its front face and reaches its back only by
/// turning over (CR 712.8c), so a land on the back of one is not a land drop
/// at all — and `FaceDef::castable_from_hand` defaults to `true`, so
/// twenty-one cards in the pool offered theirs out of hand. Twenty of those
/// are spell-fronted and were counted here; the twenty-first, Havengul
/// Laboratory, has a land front and this sweep never looked at it.
///
/// It could not see any of them and never could: it plays every
/// spell-fronted land back and asserts that what arrives is that face's own
/// types, which was perfectly true of all twenty. What tells a transforming
/// card from a modal one is Scryfall's `layout`, which is a printing and not
/// a rule a card file states, so the guard is in `xtask validate` and this
/// number is what fell out of it.
const FLOOR: usize = 32;

const ROUND_J_MODAL_LANDS: &[fn() -> CardIndex] = &[
    revitalizing_repast,
    vastwood_fortification,
    beyeen_veil,
    jwari_disruption,
    kabira_takedown,
    legion_leadership,
    waterlogged_teachings,
    bala_ged_recovery,
    makindi_stampede,
    song_mad_treachery,
    zof_consumption,
    ondu_inversion,
];

/// Every card whose front face is a spell and whose back is a land it may
/// be played as, played as that land.
///
/// One printed sentence asked of a whole family rather than of one card. A
/// modal double-faced card is a land drop *or* a spell and never both, so
/// what has to hold is that the back face arrives as a **land**, that the
/// front face's card type stayed on the other side of the card, and that it
/// entered tapped exactly when its own face says so. The last of those is
/// the assertion with teeth: the enters-tapped modifier lives on the *back*
/// face, and a reader taking the card's own top-level list would find
/// nothing there and report a clean arrival.
///
/// Asked of the compiled pool rather than of a hand-written list, for the
/// reason `the_only_lands_that_would_count_themselves_are_the_slow_ones`
/// gives -- the pool is what ships, and thirteen of these arrived in one
/// batch from one model, so the question worth asking is whether the
/// *family* holds and not whether those thirteen do.
///
/// It lives in this door although every one of these cards is filed under
/// `instants/` or `sorceries/`: what the test plays is a land drop and what
/// it asserts is how a land arrives.
#[test]
fn every_modal_back_face_land_is_played_as_the_land_it_prints() {
    let mut reached = Vec::new();
    let mut asks = Vec::new();
    for def in baylee_cards::all() {
        let [front, back] = def.faces else { continue };
        if front.types.contains(TypeSet::LAND) || !back.types.contains(TypeSet::LAND) {
            continue;
        }
        // A transforming card's back is not something a player may put onto
        // the battlefield from hand, and this is the one field separating
        // the two layouts: without it a werewolf's night side would be
        // asked for a land drop it never offers.
        if !back.castable_from_hand {
            continue;
        }
        // "As this land enters, you may pay 3 life. If you don't, it enters
        // tapped" is a question asked *before* the land is on the
        // battlefield, and `play_land_face` answers the face choice and
        // nothing else -- so the card is still in hand when it returns and
        // a perfectly good land drop reads as a refusal. Those are named
        // below rather than dropped: what a sweep did not read is the half
        // of its answer that nothing else can recover.
        if !back
            .enter_modifiers
            .iter()
            .all(|m| *m == baylee_cards_dsl::EnterModifier::Tapped)
        {
            asks.push(back.name);
            continue;
        }
        let (engine, land) = play_land_face(def.index, 1)
            .unwrap_or_else(|err| panic!("{}: the land face {err}", back.name));

        let played = types(&engine, land);
        // The whole type line and not "is it a land": a back face that
        // shares a type with its front -- The Myriad Pools is an artifact
        // land behind an artifact -- makes "the front's type is absent" a
        // sentence that is false about a correct card, and equality is the
        // claim that was meant anyway.
        assert_eq!(
            played, back.types,
            "{}: what arrived is not the types its own face prints",
            back.name
        );
        let says_tapped = back
            .enter_modifiers
            .contains(&baylee_cards_dsl::EnterModifier::Tapped);
        assert_eq!(
            is_tapped(&engine, land),
            says_tapped,
            "{}: its own face says enters-tapped = {says_tapped}",
            back.name
        );
        reached.push(def.index);
    }

    asks.sort_unstable();
    assert_eq!(
        asks, ARRIVALS_THAT_ASK,
        "the set of spell-fronted land backs whose arrival asks a question \
         has changed; each of them is a land drop this harness cannot make, \
         so a new one needs a test of its own and a departure needs this \
         list shortened"
    );
    assert!(
        reached.len() >= FLOOR,
        "only {} spell-fronted land backs were played against a floor of \
         {FLOOR}; the walk is not reaching the pool",
        reached.len()
    );
    let missing: Vec<CardIndex> = ROUND_J_MODAL_LANDS
        .iter()
        .map(|handle| handle())
        .filter(|index| !reached.contains(index))
        .collect();
    assert!(
        missing.is_empty(),
        "the sweep never reached {} of the cards it was written for: {missing:?}",
        missing.len()
    );
}

/// Fell the Profane // Fell Mire: "As this land enters, you may pay 3 life.
/// If you don't, it enters tapped."
///
/// The one card of round J's thirteen that
/// [`every_modal_back_face_land_is_played_as_the_land_it_prints`] names in
/// [`ARRIVALS_THAT_ASK`] and therefore does not play, so it is played here
/// instead -- a sweep that skips a card and leaves it untested has only
/// moved the gap.
///
/// It also records which question is *not* asked. A land drop on a
/// double-faced card asks which face only where more than one face is a
/// land; this card's front is an instant, so the drop resolves straight to
/// the Mire and the first thing anybody is asked is the Mire's own
/// "as it enters" clause. That clause is a question rather than a status,
/// so both answers are played: declining leaves it tapped and the life
/// alone, paying leaves it untapped and the life three lower.
#[test]
fn fell_mire_asks_for_three_life_after_the_face_is_chosen_and_obeys_both_answers() {
    let p0 = PlayerId::new(0);

    for (pay, tapped) in [(false, true), (true, false)] {
        let mut engine = Duel::new(if pay { 967 } else { 966 }, forest())
            .hand(0, &[fell_the_profane()])
            .start();
        keep_mulligans(&mut engine);
        reach_main_phase(&mut engine, p0);

        let life_before = engine.state().players[0].life;
        let card = in_hand(&engine, p0, fell_the_profane()).expect("the card is in hand");
        engine
            .apply(p0, PlayerAction::PlayLand { card })
            .expect("the back face is a land drop");

        let Pending::YesNo {
            prompt: crate::choice::YesNoPrompt::PayLifeOrEnterTapped { amount },
            ..
        } = engine.pending().clone()
        else {
            panic!(
                "one land face means no face question, so the life clause is \
                 the first thing asked: {:?}",
                engine.pending()
            )
        };
        assert_eq!(amount, 3, "Fell Mire asks for 3 life");
        engine.apply(p0, PlayerAction::YesNo(pay)).unwrap();
        pass_until(&mut engine, stack_is_empty);

        let mire = engine
            .state()
            .object(card)
            .expect("the land is on the battlefield");
        assert_eq!(
            is_tapped(&engine, mire.id),
            tapped,
            "paying = {pay} should leave it tapped = {tapped}"
        );
        assert_eq!(
            engine.state().players[0].life,
            life_before - if pay { 3 } else { 0 },
            "paying = {pay} costs three life and declining costs none"
        );
    }
}

/// Midgar, City of Mako is a land with an Adventure on its back, and the file
/// is `Coverage::Partial`: the land half is written and Reactor Raid's
/// reflexive "If you do, draw two cards" is not. So the two printed sentences
/// the card *does* carry are what a board can hold it to — "This land enters
/// tapped" and "{T}: Add {B}" — and both are only worth asserting together,
/// because a land that entered untapped would also make its mana and read as
/// fine.
///
/// The Adventure half is checked by its absence rather than left unsaid: the
/// card is played as a land out of hand, and nothing about that offer is a
/// spell. A second Town is deliberately *not* on the board — an enters-tapped
/// clause that was really a conditional one would still be tapped here, and
/// this land prints no condition to be wrong about.
#[test]
fn midgar_city_of_mako_enters_tapped_and_makes_the_one_colour_it_prints() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .hand(0, &[midgar_city_of_mako()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let land = play_land(&mut engine, p0, midgar_city_of_mako());
    assert!(
        entered_tapped(&engine, land),
        "\"This land enters tapped\" is unconditional on this card"
    );
    assert!(
        types(&engine, land).contains(TypeSet::LAND),
        "the face played out of hand is the land face and not the Adventure"
    );

    // A tapped land makes no mana, so the turn has to come round before the
    // second sentence can be read at all.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::Priority { player, .. } if *player == p0)
            && !is_tapped(e, land)
    });
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "nothing is floating before the ability is activated"
    );
    activate(&mut engine, p0, midgar_city_of_mako(), 0);
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Black),
        1,
        "{{T}}: Add {{B}} — one black and not a choice of five"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "and one mana in total: a Town is not a dual"
    );
    assert!(is_tapped(&engine, land), "its own tap symbol was the cost");
}

/// Brokers Hideout is two triggers reading as one sentence: "When this land
/// enters, sacrifice it. When you do, search your library for a basic
/// Forest, Plains, or Island card, put it onto the battlefield tapped, then
/// shuffle and you gain 1 life." The first half is written as
/// `Trigger::ETB`, the second as this land's own
/// `Trigger::LeavesBattlefield` — which is the reading worth playing, since
/// a land that sacrificed itself and then searched nothing looks exactly
/// like a land that never entered.
///
/// The filter is checked by the branch that finds **nothing**: with a deck
/// of Mountains the search has no legal card, and Mountain is a basic land
/// — so a card written as "search for a basic land" would still find one
/// here. Both engines gain the life, because "you gain 1 life" is a
/// separate clause and not a consequence of the search.
#[test]
fn brokers_hideout_sacrifices_itself_and_finds_one_of_the_three_types_it_names() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .hand(0, &[brokers_hideout()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let life_before = engine.state().players[0].life;
    let library_before = library_size(&engine, p0);
    play_land(&mut engine, p0, brokers_hideout());

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseCards { .. })
    });
    let Pending::ChooseCards {
        player,
        options,
        prompt,
        ..
    } = engine.pending().clone()
    else {
        panic!("the search asks which land, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the land's controller searches");
    assert_eq!(prompt, ChoicePrompt::SearchLibrary);
    assert!(!options.is_empty(), "this deck is made of Forests");
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![options[0]],
            },
        )
        .expect("a card the search offered");
    pass_until(&mut engine, |e| at_rest(e, p0));

    assert!(
        on_battlefield(&engine, p0, brokers_hideout()).is_none(),
        "\"sacrifice it\" — the land it entered as is gone"
    );
    assert!(
        in_graveyard(&engine, p0, brokers_hideout()).is_some(),
        "and it went to its owner's graveyard"
    );
    let found = on_battlefield(&engine, p0, forest()).expect("the Forest it searched up");
    assert!(
        is_tapped(&engine, found),
        "\"put it onto the battlefield tapped\""
    );
    assert_eq!(
        library_size(&engine, p0),
        library_before - 1,
        "one card left the library, and the shuffle moved none"
    );
    assert_eq!(
        engine.state().players[0].life,
        life_before + 1,
        "\"and you gain 1 life\""
    );

    // The other branch: a deck of Mountains is a deck of basic lands this
    // card may not find, so the search asks nothing at all.
    let mut lean = Duel::new(SEED, mountain())
        .hand(0, &[brokers_hideout()])
        .start();
    keep_mulligans(&mut lean);
    assert!(walk_to_own_main(&mut lean, p0), "p0 reaches its own main");
    let lean_life = lean.state().players[0].life;
    let lean_library = library_size(&lean, p0);
    play_land(&mut lean, p0, brokers_hideout());
    pass_until(&mut lean, |e| at_rest(e, p0));

    assert_eq!(
        library_size(&lean, p0),
        lean_library,
        "a Mountain is a basic land and is not a Forest, Plains or Island"
    );
    assert!(
        in_graveyard(&lean, p0, brokers_hideout()).is_some(),
        "the sacrifice does not depend on the search finding anything"
    );
    assert_eq!(
        lean.state().players[0].life,
        lean_life + 1,
        "and neither does the life, which is its own clause"
    );
}

/// Basilisk Gate's pump counts **Gates you control**, and the number is read
/// as the ability resolves. Two on the battlefield is what makes that
/// readable at all: at one Gate, "the number of Gates you control" and "one"
/// and "the source itself" are the same number, and a card counting any of
/// the three would pass. The source counts itself, so two Gates is +2/+2.
///
/// The `{2}` is paid from lands that are not the Gate, because its own tap
/// symbol is part of the cost — a test that let `tap_all_mana` take the Gate
/// would be asserting that an ability nobody could activate does nothing.
#[test]
fn basilisk_gate_pumps_by_the_number_of_gates_and_counts_itself() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                basilisk_gate(),
                basilisk_gate(),
                quiet_creature(),
                forest(),
                forest(),
            ],
        )
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let creature = on_battlefield(&engine, p0, quiet_creature()).expect("the creature to point at");
    let base = pt(&engine, creature);
    let gate = on_battlefield(&engine, p0, basilisk_gate()).expect("a Gate to activate");

    tap_mana_except(&mut engine, p0, gate);
    activate(&mut engine, p0, basilisk_gate(), 1);

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets { options, .. } = engine.pending().clone() else {
        panic!("the pump asks for a target, got {:?}", engine.pending())
    };
    assert!(
        options.contains(&creature),
        "\"target creature\" — the creature on the board is one"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseTargets {
                objects: vec![creature],
                players: vec![],
            },
        )
        .expect("a target the ability offered");
    pass_until(&mut engine, |e| at_rest(e, p0));

    assert_eq!(
        pt(&engine, creature),
        (base.0 + 2, base.1 + 2),
        "two Gates you control, and the Gate that paid counts itself"
    );
    assert!(
        is_tapped(&engine, gate),
        "its own tap symbol was part of the price"
    );
}

/// Blighted Woodland: "{3}{G}, {T}, Sacrifice this land: Search your library
/// for up to two basic land cards, put them onto the battlefield tapped,
/// then shuffle."
///
/// "Up to two" is the word this plays. The DSL says it as two
/// `Find::BATTLEFIELD_TAPPED` slots with `optional: true`, and the two
/// halves of that spelling fail differently: a card that found exactly two
/// would refuse a player who wanted one, and a card that found one would
/// quietly halve every copy in the pool. So the search is answered with
/// **both** cards and the count is asserted, and the offer's own bounds are
/// read to show that one was allowed.
#[test]
fn blighted_woodland_finds_up_to_two_basic_lands_tapped() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[blighted_woodland(), forest(), forest(), forest(), forest()],
        )
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let land = on_battlefield(&engine, p0, blighted_woodland()).expect("the land deployed");
    let library_before = library_size(&engine, p0);
    let forests_before = all_on_battlefield(&engine, p0, forest());

    tap_mana_except(&mut engine, p0, land);
    activate(&mut engine, p0, blighted_woodland(), 1);

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseCards { .. })
    });
    let Pending::ChooseCards {
        options, min, max, ..
    } = engine.pending().clone()
    else {
        panic!("the search asks which lands, got {:?}", engine.pending())
    };
    assert_eq!(
        (min, max),
        (0, 2),
        "\"up to two\" — naming none is an answer and three is not"
    );
    assert!(options.len() >= 2, "this deck is made of Forests");
    let found = vec![options[0], options[1]];
    engine
        .apply(p0, PlayerAction::ChooseObjects { objects: found })
        .expect("two cards the search offered");
    pass_until(&mut engine, |e| at_rest(e, p0));

    let arrived = all_on_battlefield(&engine, p0, forest());
    assert_eq!(
        arrived.len(),
        forests_before.len() + 2,
        "both of the two it was allowed to find arrived"
    );
    // The lands already on the board paid the {3}{G} and are tapped too, so
    // "everything is tapped" would be true of a card that put its finds down
    // untapped. The two new objects are named instead.
    let new: Vec<_> = arrived
        .iter()
        .copied()
        .filter(|id| !forests_before.contains(id))
        .collect();
    assert_eq!(new.len(), 2, "two objects that were not there before");
    assert!(
        new.iter().all(|id| is_tapped(&engine, *id)),
        "\"put them onto the battlefield tapped\""
    );
    assert_eq!(
        library_size(&engine, p0),
        library_before - 2,
        "two cards left the library"
    );
    assert!(
        in_graveyard(&engine, p0, blighted_woodland()).is_some(),
        "\"Sacrifice this land\" was part of the cost"
    );
}

/// Cori Mountain Monastery is a checkland with the unusual pair — "unless you
/// control a Plains **or** an Island" on a land that taps for {R} — and a
/// condition is untested until both of its branches fire, so it is played
/// twice off one board difference. The Island is the half worth having,
/// because a reader that took only the first of the two printed types would
/// pass the Plains test and fail nothing.
///
/// The file is `Coverage::Partial` for the {3}{R} impulse ability, which is
/// invisible from here by construction: nothing in this scenario reaches an
/// activated ability other than the mana one, and the entry condition is a
/// replacement that runs before any of it.
#[test]
fn cori_mountain_monastery_checks_for_a_plains_or_an_island_and_taps_for_red() {
    let p0 = PlayerId::new(0);

    // Neither type on the board: the printed default applies.
    let mut bare = Duel::new(SEED, forest())
        .battlefield(0, &[forest()])
        .hand(0, &[cori_mountain_monastery()])
        .start();
    keep_mulligans(&mut bare);
    assert!(walk_to_own_main(&mut bare, p0), "p0 reaches its own main");
    let tapped = play_land(&mut bare, p0, cori_mountain_monastery());
    assert!(
        entered_tapped(&bare, tapped),
        "a Forest is neither a Plains nor an Island"
    );

    // An Island, which is the second of the two types the card names.
    let mut checked = Duel::new(SEED, forest())
        .battlefield(0, &[island()])
        .hand(0, &[cori_mountain_monastery()])
        .start();
    keep_mulligans(&mut checked);
    assert!(
        walk_to_own_main(&mut checked, p0),
        "p0 reaches its own main"
    );
    let untapped = play_land(&mut checked, p0, cori_mountain_monastery());
    assert!(
        !entered_tapped(&checked, untapped),
        "\"unless you control a Plains or an Island\" — the Island is the or"
    );

    activate(&mut checked, p0, cori_mountain_monastery(), 0);
    assert_eq!(
        checked.state().players[0]
            .mana_pool
            .available(ManaColor::Red),
        1,
        "{{T}}: Add {{R}}"
    );
    assert_eq!(
        checked.state().players[0].mana_pool.total(),
        1,
        "and nothing else: this land makes one colour"
    );
}

/// Arid Archway: "This land enters tapped. When this land enters, return a
/// land you control to its owner's hand." The bounce is **mandatory** and
/// the land it returns is chosen, so the assertion with teeth is that the
/// choice is offered at all and that what it names actually leaves the
/// battlefield — a trigger that resolved against nothing looks identical to
/// a land that simply entered tapped.
///
/// The archway is itself a land its controller controls, so it is on its own
/// offer, and that is the printing rather than an oversight. The Forest is
/// named instead, which is also what makes the departure readable.
///
/// The file is `Coverage::Partial` for the surveil rider, which needs a
/// second Desert to have been returned — there is one Desert here and the
/// clause could not fire even on a finished card.
#[test]
fn arid_archway_enters_tapped_and_bounces_a_land_its_controller_names() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest()])
        .hand(0, &[arid_archway()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let archway = play_land(&mut engine, p0, arid_archway());
    assert!(
        entered_tapped(&engine, archway),
        "\"This land enters tapped\" is unconditional"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseCards { .. })
    });
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!("the bounce asks which land, got {:?}", engine.pending())
    };
    assert_eq!(
        player, p0,
        "\"a land you control\" — its controller chooses"
    );
    assert_eq!(
        (min, max),
        (1, 1),
        "the sentence is mandatory and names one land"
    );
    let grove = on_battlefield(&engine, p0, forest()).expect("the Forest is on the board");
    assert!(
        options.contains(&grove),
        "the Forest is a land its controller controls"
    );
    assert!(
        options.contains(&archway),
        "and so is the archway, which the printing does not exclude"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![grove],
            },
        )
        .expect("a land the trigger offered");
    pass_until(&mut engine, |e| at_rest(e, p0));

    assert!(
        on_battlefield(&engine, p0, forest()).is_none(),
        "the Forest it named left the battlefield"
    );
    assert!(
        in_hand(&engine, p0, forest()).is_some(),
        "\"to its owner's hand\" and not to a graveyard"
    );
    assert!(
        on_battlefield(&engine, p0, arid_archway()).is_some(),
        "and the archway stayed, having named something else"
    );

    // A tapped land makes no mana, so the second sentence waits for the
    // untap step and the main phase after it.
    cross_into_the_next_own_main(&mut engine, p0);
    assert!(
        !is_tapped(&engine, archway),
        "an ordinary untap step untaps it"
    );
    // Ability 1: the ETB trigger is this card's ability 0.
    activate(&mut engine, p0, arid_archway(), 1);
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Colorless),
        2,
        "{{T}}: Add {{C}}{{C}} — two, which is what pays for the bounce"
    );
}

/// Scorched Ruins makes four colourless off one tap, which is the whole
/// reason the card has a drawback, and the drawback is the half this file
/// cannot write: "If this land would enter, sacrifice two untapped lands
/// instead" is a replacement charging a price in permanents and
/// `EnterModifier` has no variant for it.
///
/// So the land is put onto the battlefield directly, which is the honest
/// scenario for a `Coverage::Partial` of this shape: the entry is the part
/// that does not exist, and starting the land in play neither asserts that
/// it works nor pretends it was paid for. What is asserted is the four —
/// **and** that they are four of one kind, because a land that made one of
/// each colour would have the same total.
#[test]
fn scorched_ruins_taps_for_four_colourless() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[scorched_ruins()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let ruins = on_battlefield(&engine, p0, scorched_ruins()).expect("the land is in play");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "nothing is floating before the tap"
    );
    activate(&mut engine, p0, scorched_ruins(), 0);
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Colorless),
        4,
        "{{T}}: Add {{C}}{{C}}{{C}}{{C}}"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "and all four are colourless"
    );
    assert!(is_tapped(&engine, ruins), "its own tap symbol was the cost");
}

/// Three shelf lands with one printed sentence between them — "this land
/// enters tapped" — and two of them a mana ability to go with it. They are
/// played together because the assertion that matters is the pair: a land
/// that entered untapped would still make its mana, and a colour is only a
/// claim beside a total.
///
/// Cryptic Spires is the third and carries **no ability at all**, which is
/// its `Coverage::Partial` made visible: "add one mana of either of the
/// circled colors" names a choice made while building a deck, and the DSL
/// has no deck-construction vocabulary — so a card that quietly gave it a
/// colour would be inventing one. The empty ability list is asserted rather
/// than assumed.
#[test]
fn three_shelf_taplands_enter_tapped_and_make_the_colour_they_print() {
    let p0 = PlayerId::new(0);

    for (card, colour) in [
        (dakmor_salvage(), ManaColor::Black),
        (spinerock_knoll(), ManaColor::Red),
    ] {
        let mut engine = Duel::new(SEED, forest()).hand(0, &[card]).start();
        keep_mulligans(&mut engine);
        assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");
        let land = play_land(&mut engine, p0, card);
        assert!(
            entered_tapped(&engine, land),
            "\"This land enters tapped\" is unconditional on this card"
        );

        cross_into_the_next_own_main(&mut engine, p0);
        activate(&mut engine, p0, card, 0);
        assert_eq!(
            engine.state().players[0].mana_pool.available(colour),
            1,
            "the one colour this land's ability prints"
        );
        assert_eq!(
            engine.state().players[0].mana_pool.total(),
            1,
            "and nothing beside it"
        );
    }

    let mut spires = Duel::new(SEED, forest())
        .hand(0, &[cryptic_spires()])
        .start();
    keep_mulligans(&mut spires);
    assert!(walk_to_own_main(&mut spires, p0), "p0 reaches its own main");
    let land = play_land(&mut spires, p0, cryptic_spires());
    assert!(entered_tapped(&spires, land), "it enters tapped too");

    cross_into_the_next_own_main(&mut spires, p0);
    assert!(
        !is_tapped(&spires, land),
        "and untaps like any other permanent"
    );
    let Pending::Priority { legal, .. } = spires.pending().clone() else {
        panic!("expected priority, got {:?}", spires.pending())
    };
    assert!(
        !legal.abilities.iter().any(|(id, _)| *id == land),
        "Cryptic Spires offers nothing: the colours are circled as a deck is \
         built, and that is the half this card does not have"
    );
}

/// Shizo, Death's Storehouse is a **legendary** land, and the type line is
/// the part worth playing: CR 704.5j applies the legend rule to any
/// permanent with the supertype, not only to creatures, and a land written
/// as a plain `Land` would sit on the battlefield in pairs with every other
/// reading of it correct.
///
/// So two are played, one turn apart, and the survivor is the one its
/// controller keeps. The mana ability is asserted on that survivor, because
/// a land that lost the legend rule and a land that never made mana are
/// different failures and the test should not be able to confuse them.
///
/// The file is `Coverage::Partial` for the {B}, {T} fear grant — fear is a
/// keyword bit no rule reads — and nothing here activates it.
#[test]
fn shizo_is_legendary_and_the_survivor_still_taps_for_black() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .hand(0, &[shizo_death_s_storehouse(), shizo_death_s_storehouse()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let first = play_land(&mut engine, p0, shizo_death_s_storehouse());
    assert!(
        !entered_tapped(&engine, first),
        "Shizo prints no enters-tapped clause"
    );
    assert_eq!(
        all_on_battlefield(&engine, p0, shizo_death_s_storehouse()).len(),
        1,
        "one is one"
    );

    cross_into_the_next_own_main(&mut engine, p0);
    let second = play_land(&mut engine, p0, shizo_death_s_storehouse());

    // CR 704.5j is a state-based action that asks rather than picks: the
    // controller keeps one. Keeping the newcomer is the answer that makes
    // the assertion below about the rule and not about which object the
    // engine happened to leave alone.
    let Pending::LegendChoice { player, options } = engine.pending().clone() else {
        panic!(
            "two legendary permanents ask the legend rule, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "their controller chooses");
    assert_eq!(options.len(), 2, "both Shizos are on the offer");
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![second],
            },
        )
        .expect("the one it named was one of the two");
    pass_until(&mut engine, |e| at_rest(e, p0));

    let standing = all_on_battlefield(&engine, p0, shizo_death_s_storehouse());
    assert_eq!(
        standing.len(),
        1,
        "the legend rule (CR 704.5j) is about permanents and not about creatures"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Graveyard(p0)).len(),
        1,
        "and the one that lost went to its owner's graveyard"
    );

    activate(&mut engine, p0, shizo_death_s_storehouse(), 0);
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Black),
        1,
        "{{T}}: Add {{B}} on the one that is still there"
    );
}

/// Vesuva: "You may have this land enter tapped as a copy of any land on the
/// battlefield." The copy is what this plays, and the card is
/// `Coverage::Partial` for the "tapped" half — `AbilityDef::CopyOnEnter`
/// carries no enter modifier, so what arrives is the copy untapped.
///
/// A **Forest** is the land to copy, because the copy has to be readable
/// from two sides that a wrong answer separates: the types it now has, and
/// the mana its intrinsic ability makes (CR 305.6, which is a land's type
/// line and not an ability anybody copied). A Vesuva that took the name and
/// not the type line would tap for nothing.
#[test]
fn vesuva_enters_as_a_copy_of_a_land_on_the_battlefield() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest()])
        .hand(0, &[vesuva()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let model = on_battlefield(&engine, p0, forest()).expect("a Forest to copy");
    engine
        .apply(
            p0,
            PlayerAction::PlayLand {
                card: in_hand(&engine, p0, vesuva()).expect("Vesuva is in hand"),
            },
        )
        .expect("a land drop");

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets { options, .. } = engine.pending().clone() else {
        panic!("the copy asks which land, got {:?}", engine.pending())
    };
    assert!(
        options.contains(&model),
        "\"any land on the battlefield\" — the Forest is one"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseTargets {
                objects: vec![model],
                players: vec![],
            },
        )
        .expect("a land the ability offered");
    pass_until(&mut engine, |e| at_rest(e, p0));

    // The object is still Vesuva's card — a copy effect changes an object's
    // characteristics and not which card it came off (CR 707.2), so it is
    // found by its own index and read through the layer system.
    let copy = on_battlefield(&engine, p0, vesuva()).expect("Vesuva is on the battlefield");
    assert_ne!(copy, model, "and it is not the Forest it copied");
    let chars = engine
        .state()
        .object(copy)
        .expect("the copy exists")
        .characteristics();
    assert_eq!(
        engine.state().names.get(chars.name),
        "Forest",
        "a copy takes the copiable values, name included (CR 707.2)"
    );

    assert_eq!(
        types(&engine, copy),
        types(&engine, model),
        "and the whole type line with it"
    );

    activate(&mut engine, p0, vesuva(), 0);
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Green),
        1,
        "and taps for green off the type line it copied (CR 305.6)"
    );
}

/// Obscura Storefront is Brokers Hideout's sibling in a different wedge —
/// "search your library for a basic Plains, Island, or Swamp card" — and it
/// is played the same way for the same reason: the branch that finds
/// **nothing** is what separates the three types it prints from "a basic
/// land". A Forest is a basic land and is none of the three.
///
/// The file is `Coverage::Partial` for a reason this scenario cannot see and
/// says so rather than leaving it: the printed "When you do" is a reflexive
/// trigger (CR 603.12), and here the search sits in the same ability as the
/// sacrifice. Nothing below responds to anything, so the two readings agree.
#[test]
fn obscura_storefront_searches_for_one_of_the_three_basics_it_names() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, island())
        .hand(0, &[obscura_storefront()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let life_before = engine.state().players[0].life;
    play_land(&mut engine, p0, obscura_storefront());
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseCards { .. })
    });
    let Pending::ChooseCards { options, .. } = engine.pending().clone() else {
        panic!("the search asks which land, got {:?}", engine.pending())
    };
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![options[0]],
            },
        )
        .expect("a card the search offered");
    pass_until(&mut engine, |e| at_rest(e, p0));

    let found = on_battlefield(&engine, p0, island()).expect("the Island it searched up");
    assert!(
        is_tapped(&engine, found),
        "\"put it onto the battlefield tapped\""
    );
    assert!(
        in_graveyard(&engine, p0, obscura_storefront()).is_some(),
        "\"sacrifice it\" — and it went to its owner's graveyard"
    );
    assert_eq!(
        engine.state().players[0].life,
        life_before + 1,
        "\"and you gain 1 life\""
    );

    // A deck of Forests: a basic land this card may not find.
    let mut lean = Duel::new(SEED, forest())
        .hand(0, &[obscura_storefront()])
        .start();
    keep_mulligans(&mut lean);
    assert!(walk_to_own_main(&mut lean, p0), "p0 reaches its own main");
    let lean_library = library_size(&lean, p0);
    play_land(&mut lean, p0, obscura_storefront());
    pass_until(&mut lean, |e| at_rest(e, p0));
    assert_eq!(
        library_size(&lean, p0),
        lean_library,
        "a Forest is a basic land and is not a Plains, Island or Swamp"
    );
}

/// Barad-dûr enters tapped **unless you control a legendary creature**,
/// which is the rarer half of the checkland sentence: the usual one looks at
/// land types, and a reader that matched on a supertype without also
/// requiring the card type would be satisfied by Barad-dûr itself, which is
/// a legendary land sitting right there. So the negative branch has the land
/// alone on an otherwise empty board, and the positive one adds
/// Jin-Gitaxias.
///
/// The file is `Coverage::Partial` for the {X}{X}{B} amass ability, and
/// nothing here reaches it: `Effect::Amass` carries a fixed number where the
/// card prints X, and no `Condition` says a creature died this turn.
#[test]
fn barad_dur_checks_for_a_legendary_creature_and_not_for_itself() {
    let p0 = PlayerId::new(0);

    let mut bare = Duel::new(SEED, forest()).hand(0, &[barad_dur()]).start();
    keep_mulligans(&mut bare);
    assert!(walk_to_own_main(&mut bare, p0), "p0 reaches its own main");
    let tapped = play_land(&mut bare, p0, barad_dur());
    assert!(
        entered_tapped(&bare, tapped),
        "a legendary *land* is not a legendary creature, not even this one"
    );

    let mut held = Duel::new(SEED, forest())
        .battlefield(0, &[jin_gitaxias()])
        .hand(0, &[barad_dur()])
        .start();
    keep_mulligans(&mut held);
    assert!(walk_to_own_main(&mut held, p0), "p0 reaches its own main");
    let untapped = play_land(&mut held, p0, barad_dur());
    assert!(
        !entered_tapped(&held, untapped),
        "Jin-Gitaxias is a legendary creature and turns the clause off"
    );

    activate(&mut held, p0, barad_dur(), 0);
    assert_eq!(
        held.state().players[0]
            .mana_pool
            .available(ManaColor::Black),
        1,
        "{{T}}: Add {{B}}"
    );
}

/// Jidoor is a Town — a land on the front of a card whose back is an
/// Adventure — and the half worth playing is that the land drop is the land.
/// "Overture" is a {4}{U}{U} sorcery on the other face, so a card offering
/// its back out of hand would be a six-mana spell anybody could play for
/// free as a land, which is exactly the fault twenty-one cards in this pool
/// had this morning.
///
/// The file is `Coverage::Partial` for Overture's own text — "mills half
/// their library, rounded down" has no `Amount` that halves — and the
/// Adventure is therefore checked by its absence rather than cast.
#[test]
fn jidoor_is_played_as_the_town_and_taps_for_blue() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .hand(0, &[jidoor_aristocratic_capital()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let land = play_land(&mut engine, p0, jidoor_aristocratic_capital());
    assert!(
        entered_tapped(&engine, land),
        "\"This land enters tapped\" is unconditional"
    );
    assert!(
        types(&engine, land).contains(TypeSet::LAND),
        "what arrived is the Town and not the sorcery on its back"
    );
    assert!(
        !types(&engine, land).contains(TypeSet::SORCERY),
        "and the Adventure face stayed on the other side of the card"
    );

    cross_into_the_next_own_main(&mut engine, p0);
    activate(&mut engine, p0, jidoor_aristocratic_capital(), 0);
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Blue),
        1,
        "{{T}}: Add {{U}}"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "one blue and nothing else"
    );
}

/// Dungeon Descent and Howltooth Hollow are the two remaining shelf taplands
/// with one colour between them, and they are here for the same pair the
/// other three were: entering tapped and then making the colour printed
/// beside it, neither being worth asserting alone.
///
/// Both carry a `Coverage::Partial` for a mechanic with no vocabulary at all
/// — venturing into the dungeon, and hideaway — and both of those hang off a
/// **second** activated ability. So the ability list is read: one entry
/// each, which is the gap made countable rather than described.
///
/// The board is what makes that count mean something. `can_afford` gates
/// every entry in the offer, so a count taken where the second ability could
/// not have been paid for would keep reading one after the ability was
/// written. Dungeon Descent's is "{4}, {T}, Tap an untapped legendary
/// creature you control", so four Forests and Jin-Gitaxias stand beside it;
/// Howltooth Hollow's is "{B}, {T}", and its own tap is part of that price,
/// so the black comes from a Swamp. Both are asked in a main phase with an
/// empty stack, which is the sorcery timing one of them needs.
#[test]
fn the_last_two_shelf_taplands_enter_tapped_and_offer_one_ability_each() {
    let p0 = PlayerId::new(0);

    for (card, colour, payment) in [
        (
            dungeon_descent(),
            ManaColor::Colorless,
            &[forest(), forest(), forest(), forest(), jin_gitaxias()][..],
        ),
        (howltooth_hollow(), ManaColor::Black, &[swamp()][..]),
    ] {
        let mut engine = Duel::new(SEED, forest())
            .battlefield(0, payment)
            .hand(0, &[card])
            .start();
        keep_mulligans(&mut engine);
        assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");
        let land = play_land(&mut engine, p0, card);
        assert!(entered_tapped(&engine, land), "\"This land enters tapped\"");

        cross_into_the_next_own_main(&mut engine, p0);
        // The price is **floated**, not merely stood on the board:
        // `can_afford` reads the pool, so an ability with any mana cost at
        // all is absent from an offer taken over untapped lands — which is
        // how this pin first passed for the wrong reason. Everything but the
        // land itself is tapped, because the land is what both the mana
        // ability and the missing one tap.
        tap_mana_except(&mut engine, p0, land);
        let Pending::Priority { legal, .. } = engine.pending().clone() else {
            panic!("expected priority, got {:?}", engine.pending())
        };
        assert_eq!(
            legal.abilities.iter().filter(|(id, _)| *id == land).count(),
            1,
            "the mana ability, and not the venture or hideaway one beside it \
             — whose price is floating in this pool"
        );

        let before = engine.state().players[0].mana_pool.available(colour);
        let before_total = engine.state().players[0].mana_pool.total();
        activate(&mut engine, p0, card, 0);
        assert_eq!(
            engine.state().players[0].mana_pool.available(colour),
            before + 1,
            "the one colour its mana ability prints"
        );
        assert_eq!(
            engine.state().players[0].mana_pool.total(),
            before_total + 1
        );
    }
}

/// Grove of the Guardian's token ability costs "{3}{G}{W}, {T}, Tap two
/// untapped creatures you control, Sacrifice this land", and
/// `CostPart::TapOther` names exactly one permanent and carries no count —
/// so the file is `Coverage::Partial` and the land offers its mana ability
/// and nothing else.
///
/// The board is built so that the **price** is not the reason. `can_afford`
/// gates every entry in the offer, so a pin standing on a board that could
/// not pay would keep passing after the ability was written and prove
/// nothing: three Forests and two Plains are the {3}{G}{W} in the two
/// colours it names, and two untapped creatures are standing there to be
/// tapped. What is missing is the sentence, and this is **meant to fail**
/// the day a `CostPart` can carry a count.
#[test]
fn grove_of_the_guardian_offers_only_the_half_its_coverage_says_is_built() {
    let p0 = PlayerId::new(0);
    let mut grove = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                grove_of_the_guardian(),
                quiet_creature(),
                quiet_creature(),
                forest(),
                forest(),
                forest(),
                plains(),
                plains(),
            ],
        )
        .start();
    keep_mulligans(&mut grove);
    reach_main_phase(&mut grove, p0);
    let land = on_battlefield(&grove, p0, grove_of_the_guardian()).expect("the land is in play");
    // `can_afford` reads the pool and not the board, so the {3}{G}{W} is
    // floated off the five lands beside it — while the land itself and the
    // two creatures stay untapped, because those are what the missing
    // ability taps. (Llanowar Elves makes mana too, which is exactly why
    // this is `tap_mana_where` and not `tap_mana_except`.)
    let creatures = all_on_battlefield(&grove, p0, quiet_creature());
    assert_eq!(creatures.len(), 2, "the two the ability would tap");
    tap_mana_where(&mut grove, p0, |id| id != land && !creatures.contains(&id));
    let Pending::Priority { legal, .. } = grove.pending().clone() else {
        panic!("expected priority, got {:?}", grove.pending())
    };
    assert_eq!(
        legal.abilities.iter().filter(|(id, _)| *id == land).count(),
        1,
        "only the mana ability, although the {{3}}{{G}}{{W}} is floating and \
         the two untapped creatures are standing here"
    );
    activate(&mut grove, p0, grove_of_the_guardian(), 0);
    assert_eq!(
        grove.state().players[0]
            .mana_pool
            .available(ManaColor::Colorless),
        1,
        "{{T}}: Add {{C}} is the half that is built"
    );
}

/// Land Cap: "{T}: Add {W} or {U}. Put a depletion counter on this land."
/// One activation, two effects, and the card is only itself when both
/// happen — a land that made the mana and skipped the counter is a
/// Tundra, and one that placed the counter and made nothing is a blank.
///
/// The choice is the other half: "{W} **or** {U}" is a question asked as the
/// ability resolves, so the answer is given and the pool is then read for
/// that colour *and* for its total, because a land that quietly made both
/// would satisfy either colour alone.
///
/// The file is `Coverage::Partial` for the two clauses that read the counter
/// back — the untap lock and the upkeep removal — and this pins the first:
/// the land untaps on the next turn with the counter still on it, which the
/// printing forbids. That assertion is meant to be deleted the day a
/// `Modifier` can make an untap lock conditional on a counter.
#[test]
fn land_cap_pays_for_its_mana_with_a_depletion_counter_it_cannot_yet_read() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest()).hand(0, &[land_cap()]).start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let land = play_land(&mut engine, p0, land_cap());
    assert!(
        !entered_tapped(&engine, land),
        "Land Cap prints no enters-tapped clause"
    );

    activate(&mut engine, p0, land_cap(), 0);
    // Not `if let`: a question that is never asked and a question answered
    // wrongly read the same through one, and the whole point of "or" is that
    // it is asked.
    let Pending::ChooseColor { player, options } = engine.pending().clone() else {
        panic!(
            "\"Add {{W}} or {{U}}\" asks which, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the seat that tapped it chooses");
    assert_eq!(
        options,
        vec![ManaColor::White, ManaColor::Blue],
        "the two the card prints, in the order it prints them"
    );
    engine
        .apply(p0, PlayerAction::ChooseColor(ManaColor::White))
        .expect("a colour the ability offered");
    pass_until(&mut engine, |e| at_rest(e, p0));

    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::White),
        1,
        "the colour that was named"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "and one mana in total: \"or\" is a choice and not a pair"
    );
    assert_eq!(
        counters_on(&engine, land, counters::DEPLETION),
        1,
        "\"Put a depletion counter on this land\" is the price of the colour"
    );

    // The pin. "This land doesn't untap during your untap step if it has a
    // depletion counter on it" has no `Modifier` that reads a counter, so it
    // is not built — and this is where that shows.
    cross_into_the_next_own_main(&mut engine, p0);
    assert_eq!(
        counters_on(&engine, land, counters::DEPLETION),
        1,
        "nothing removed it: the upkeep clause is not built either"
    );
    assert!(
        !is_tapped(&engine, land),
        "and it untapped anyway, which the printing forbids — delete this \
         assertion when a Modifier can hang an untap lock on a counter"
    );
}

